Filter on Province_State = 'California', sum daily_new_deaths across 2021, including Unassigned/Out-of-state rows.

run_query: total covid deaths in California for 2021 from t0.

run_query {"sql": "SELECT SUM(\"daily_new_deaths\") AS \"total_deaths_2021\"\nFROM \"t0\"\nWHERE \"Province_State\" = 'California'\n  AND \"date\" >= DATE '2021-01-01'\n  AND \"date\" <= DATE '2021-12-31'", "summary": "Total COVID-19 deaths recorded in California across all of 2021, summed from the daily US deaths dataset (t0), including any Unassigned and Out-of-state rows."}
